{"content":""""Persistent shared JSON cache for public demonstration profiles."""
import json,os,time
from app.config import CACHE_PATH,CACHE_TTL

def _read_entries():
    try:
        with open(CACHE_PATH,encoding='utf-8') as f: entries=json.load(f)
    except (OSError,ValueError):
        return {}
    return entries if isinstance(entries,dict) else {}

def _write_entries(entries):
    directory=os.path.dirname(CACHE_PATH)
    if directory: os.makedirs(directory,exist_ok=True)
    tmp='%s.%d.tmp'%(CACHE_PATH,os.getpid())
    with open(tmp,'w',encoding='utf-8') as f: json.dump(entries,f)
    os.replace(tmp,CACHE_PATH)

def get_or_load(key,loader,now=None):
    current=time.time() if now is None else now
    entries=_read_entries()
    entry=entries.get(key)
    if isinstance(entry,dict):
        stored_at=entry.get('stored_at')
        if isinstance(stored_at,(int,float)) and current-stored_at<CACHE_TTL:
            return entry.get('value')
    value=loader()
    entries[key]={'stored_at':current,'value':value}
    _write_entries(entries)
    return value
